        offers.append((l, r))

    results = []

    for x in range(1, n + 1):
        occupied = set()
        for l, r in offers:
            duration = r - l + 1
            if duration >= x:
                # Check if all days in [l, r] are free
                all_free = True
                for day in range(l, r + 1):
                    if day in occupied:
                        all_free = False
                        break

                if all_free:
                    for day in range(l, r + 1):
                        occupied.add(day)

        results.append(str(len(occupied)))

    return '\n'.join(results) + '\n'

import sys

def solution(s):
    if not s or len(s.strip()) == 0:
        return s

    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line.rstrip('\r')) for line in lines[1:n+1]]

    # Find connected components (rooms)
    visited = [[False] * m for _ in range(n)]
    rooms = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                room = []
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    r, c = stack.pop()
                    room.append((r, c))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.' and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                rooms.append(room)

    # For each room, determine its bounding box
    def get_bbox(room):
        min_r, max_r, min_c, max_c = float('inf'), float('-inf'), float('inf'), float('-inf')
        for r, c in room:
            min_r = min(min_r, r)
            max_r = max(max_r, r)
            min_c = min(min_c, c)
            max_c = max(max_c, c)
        return min_r, max_r, min_c, max_c

    # Mark all cells that should be free (in any room's bounding box)
    should_be_free = [[False] * m for _ in range(n)]
    for room in rooms:
        min_r, max_r, min_c, max_c = get_bbox(room)
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                should_be_free[r][c] = True

    # Keep original free cells, check if we need to fill in walls
    result = [row[:] for row in grid]
    for i in range(n):
        for j in range(m):
            if should_be_free[i][j] and grid[i][j] == '*':
                result[i][j] = '.'

    return '\n'.join(''.join(row) for row in result) + '\n'

# Test cases for pytest
def run_tests():
    test_cases = [
        ('4 5\n.....\n.....\n..***\n..*..\n', '.....\n.....\n.....\n.....\n'),
        ('5 5\n.*.*.\n*****\n.*.*.\n*****\n.*.*.\n', '.*.*.\n*****\n.*.*.\n*****\n.*.*.\n'),
        ('6 7\n***.*.*\n..*.*.*\n*.*.*.*\n*.*.*.*\n..*...*\n*******\n', '***...*\n..*...*\n..*...*\n..*...*\n..*...*\n*******\n'),
        ('3 3\n...\n...\n...\n', '...\n...\n...\n'),
        ('5 5\n.....\n.....\n.....\n.....\n.....\n', '.....\n.....\n.....\n.....\n.....\n'),
        ('2 2\n..\n..~\n', '..\n..\n'),  # Edge case
        ('1 1\n.\n', '.\n'),
        ('1 1\n*\n', '*\n'),
    ]

    passed = 0
    for i, (inp, expected) in enumerate(test_cases):
        result = solution(inp)
        if result == expected:
            print(f"TEST {i+1} PASSED")
            passed += 1
        else:
            print(f"TEST {i+1} FAILED")
            print(f"Input: {inp}")
            print(f"Expected: {repr(expected)}")
            print(f"Got:      {repr(result)}")

    print(f"\nPassed: {passed}/{len(test_cases)}")
    return passed == len(test_cases)

if __name__ == "__main__":
    run_tests()

