        for submask in range(1, mask - mask_ones):
            if (submask & mask) == submask:  # submask is part of mask
                rest = mask ^ submask
                if dp[submask] != 0 and dp[rest] != 0:
                    cnt = dp[submask] + dp[rest]
                    if cnt < min_v:
                        min_v = cnt
                        if min_v == 1:  # Can't get better than 1
                            break

        return min_v

    return dp((1 << n) - 1)

