def solution(input_str):
    lines = input_str.strip().split('\n')

    if len(lines) < 2:
        return "0\n"

    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    # Parse parities
    parity_line = lines[m + 1] if len(lines) > m + 1 else ""
    if not parity_line.strip():
        parities = []
    else:
        parities = list(map(int, parity_line.split()))

    # Adjust parities length
    required_n = len(parities)
    if required_n < n:
        parities = parities + (0,) * (n - required_n)

    # Collect vertices needing odd visits
    odd_vertices = [i + 1 for i in range(n) if parities[i] == 1]

    # Edge case: no odd vertices -> empty path
    if not odd_vertices:
        return "0\n"

    # Odd number of odd-required vertices -> impossible
    if len(odd_vertices) % 2 != 0:
        return "-1\n"

    # Only 1 odd vertex -> impossible (need pairs, and path endpoints are 2)
    if len(odd_vertices) == 1:
        return "-1\n"

    # No edges at all -> can only visit vertices if they form a valid path
    if len(adj[0]) == 0:  # No edges
        return "0\n"

    # BFS to find shortest path between two vertices
    def bfs_path(start, end):
        if start == end:
            return [start]
        visited = {start}
        parent = {start: None}
        queue = deque([start])

        while queue:
            u = queue.popleft()
            if u == end:
                break
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    parent[v] = u
                    queue.append(v)

        if end not in parent:
            return None

        path = []
        curr = end
        while curr is not None:
            path.append(curr)
            curr = parent[curr]
        return path[::-1]

    # Build path by connecting odd vertices
    result_path = []
    for i in range(len(odd_vertices)):
        if i == 0:
            result_path.append(odd_vertices[0])
        else:
            # Connect to previous odd vertex
            prev_path = bfs_path(result_path[-1], odd_vertices[i])
            if prev_path is None:
                return "-1\n"
            result_path.extend(prev_path[1:])

    if not result_path:
        return "0\n"

    # Build the output
    result = " ".join(map(str, result_path))
    return f"{len(result_path)}\n{result}\n"

