        return mx

    def gradient_descent(center, planets, tolerance=1e-10, steps=1000):
        change = 6.0  # initial step size

        for _ in range(steps):
            max_d = max_dist(center, planets)
            farthest = [p for p in planets if dist(center, p) > max_d - 1e-9]

            if not farthest:
                break

            # Move center towards farthest points
            for i in range(3):
                delta = sum(farthest[j][i] for j in range(len(farthest))) / len(farthest) - center[i]
                center[i] += delta * change

            if change < tolerance:
                break
            change *= 0.95

        return center

