def get_divisors(n):
    """Get all divisors of n greater than 1, sorted"""
    divs = []
    i = 2
    while i * i <= n:
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
        i += 1
    if n > 1:
        divs.append(n)
    return sorted(divs)

