def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i in range(n - 1):
        u, v = map(int, lines[2 + i].split())
        adj[u - 1].append(v - 1)
        adj[v - 1].append(u - 1)

    # Build degree array
    deg = [len(adj[i]) for i in range(n)]

    # Check if star graph
    center = -1
    if max(deg) == n - 1:
        for i, d in enumerate(deg):
            if d == n - 1:
                center = i
                break

    if n == 2:
        # Two nodes always connect to each other (trivial), collect both
        return str(sum(a))

    if center != -1:
        # Star graph case with n > 2
        # Get all leaf values (excluding center)
        leaves = [a[i] for i in range(n) if deg[i] == 1]

        # Sort in descending order
        sorted_leaves = sorted(leaves, reverse=True)

        # If at least 2 leaves, return second largest (cooperative optimal)
        if len(sorted_leaves) >= 2:
            return str(sorted_leaves[1])
        else:
            # Edge case with fewer than 2 leaves
            return str(min(leaves + [a[center]]) if leaves else a[center])
    else:
        # Non-star tree: can visit all nodes
        return str(sum(a))

