        result = []
        visited = set()
        path = [start]

        while len(result) < 3:
            visited = set()
            path = [start]
            found = False
            neighbor_seen = set()

            q = deque([start])
            parent = {start: None}

            while q and len(result) < 3:
                curr = q.popleft()

                if curr == end:
                    # Reconstruct path
                    path = []
                    node = end
                    while parent[node] is not None:
                        path.append(node)
                        node = parent[node]
                    path.append(start)
                    path.reverse()

                    # Check if this path uses any edge from previous paths
                    path_edges = set()
                    for i in range(len(path) - 1):
                        a, b = path[i], path[i+1]
                        if a > b:
                            a, b = b, a
                        path_edges.add((a, b))

                    shared = False
                    for prev_path in result:
                        for i in range(len(prev_path) - 1):
                            a, b = prev_path[i], prev_path[i+1]
                            if a > b:
                                a, b = b, a
                            if (a, b) in path_edges:
                                shared = True
                                break
                        if shared:
                            break

                    if not shared:
                        result.append(path)
                    found = True
                    break

                if curr in visited and len(result) < 3:
                    continue
                visited.add(curr)

                for next_node in adj[curr]:
                    if next_node == parent[curr]:
                        continue

                    if next_node in neighbor_seen and len(result) < 3:
                        continue
                    neighbor_seen.add(next_node)

                    if next_node not in visited or next_node in neighbor_seen:
                        continue

