def solution(input_str):
    """
    Solves the CNF satisfiability problem (k-SAT with limited variable occurrences).
    Uses 2-SAT implication graph approach with Tarjan's SCC algorithm.
    """
    lines = input_str.strip().split('\n')
    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])

    # Implication graph: nodes 1..m are positive literals, nodes m+1..2m are negative literals
    adj = [[] for _ in range(2 * m + 1)]

    # Build the implication graph
    # For a clause (l1 ∨ l2 ∨ ... ∨ lk), we add implications ¬li → lj for all i ≠ j
    for i in range(n):
        parts = lines[i + 1].split()
        kl = int(parts[0])
        literals = list(map(int, parts[1:]))

        for j in range(kl):
            for k in range(kl):
                if j != k:
                    # ¬literals[j] → literals[k]
                    adj[-literals[j]].append(literals[k])

    # Tarjan's algorithm for finding SCCs
    visited = [False] * (2 * m + 1)
    ids = [-1] * (2 * m + 1)
    low = [0] * (2 * m + 1)
    on_stack = [False] * (2 * m + 1)
    stack = []
    scc_id = [-1] * (2 * m + 1)
    id_counter = [0]
    scc_counter = [0]

    def tarjan(at):
        stack.append(at)
        on_stack[at] = True
        ids[at] = low[at] = id_counter[0]
        id_counter[0] += 1

        for to in adj[at]:
            if ids[to] == -1:
                tarjan(to)
                low[at] = min(low[at], low[to])
            elif on_stack[to]:
                low[at] = min(low[at], ids[to])

        if low[at] == ids[at]:
            while stack:
                node = stack.pop()
                on_stack[node] = False
                scc_id[node] = scc_counter[0]
                if node == at:
                    break
            scc_counter[0] += 1

    for i in range(1, 2 * m + 1):
        if ids[i] == -1:
            tarjan(i)

    # Check for unsatisfiability: if variable i and its negation are in same SCC
    for i in range(1, m + 1):
        if scc_id[i] == scc_id[i + m]:
            return "NO"

    # Assign variables: for each variable, pick the literal in higher-indexed SCC
    ans = []
    for i in range(1, m + 1):
        if scc_id[i] > scc_id[i + m]:
            ans.append("0")  # x_i = FALSE (put positive literal in SCC after negative in topo order)
        else:
            ans.append("1")  # x_i = TRUE

    return "YES\n" + "".join(ans)

def solution(input_str):
    lines = input_str.strip().split('\n')

    if not lines:
        return "NO"

    n = int(lines[0])
    cards = []
    for i in range(1, 2 * n + 1):
        parts = lines[i].split()
        a, b = int(parts[0]), int(parts[1])
        cards.append((a, b))

    def is_balanced(seq):
        """Check if sequence forms a balanced bracket sequence with multi-type matching"""
        stack = []
        for x in seq:
            if x > 0:
                stack.append(x)
            else:
                if not stack or stack[-1] != -x:
                    return False
                stack.pop()
        return len(stack) == 0

    def try_order(ordered_cards):
        front = [c[0] for c in ordered_cards]
        back = [c[1] for c in ordered_cards]
        return is_balanced(front) and is_balanced(back)

    def solution_helper(cards):
        # Sort strategy: separate opens and closes, then interleave
        a_pos = [(a, b) for a, b in cards if a > 0]  # opens for front
        a_neg = [(a, b) for a, b in cards if a < 0]  # closes for front
        b_pos = [(a, b) for a, b in cards if b > 0]  # opens for back
        b_neg = [(a, b) for a, b in cards if b < 0]  # closes for back

        # Sort by back value to help balance back sequence
        a_pos.sort(key=lambda x: x[1])
        a_neg.sort(key=lambda x: x[1], reverse=True)
        b_pos.sort(key=lambda x: x[1])
        b_neg.sort(key=lambda x: x[1], reverse=True)

        # Concatenate: opens first, then closes
        ordered = a_pos + a_neg

        if try_order(ordered):
            return ordered

        # Try: shuffles between opens and closes
        if len(a_pos) == len(a_neg):
            result = list(a_pos) + list(a_neg)
            for i in range(min(len(result) - 1, 2 * n)):
                shifted = result[i:] + result[:i]
                if try_order(shifted):
                    return shifted

        # Try: sort front first by front value
        if len(cards) <= 20:
            import itertools
            for perm in itertools.permutations(cards):
                if try_order(list(perm)):
                    return list(perm)

        return None

    result = solution_helper(cards)

    if result is None:
        return "NO"

    output = "YES\n"
    for a, b in result:
        output += f"{a} {b}\n"
    return output

