    def is_bitonic(arr):
        """Check if array is bitonic (increases to peak, then decreases)"""
        if len(arr) <= 1:
            return True

        max_idx = 0
        max_val = arr[0]
        for i in range(len(arr)):
            if arr[i] > max_val:
                max_val = arr[i]
                max_idx = i

        # Check if elements increase until peak (before and including peak)
        for i in range(max_idx):
            if arr[i] >= arr[i+1]:
                return False

        # Check if elements decrease after peak
        for i in range(max_idx + 1, len(arr)):
            if arr[i-1] <= arr[i]:
                return False

        return True

    # Check if all rows and columns are bitonic
    row_bitonic = all(is_bitonic(matrix[i]) for i in range(n))
    col_bitonic = True
    for j in range(m):
        col = [matrix[i][j] for i in range(n)]
