from collections import deque

def bfs(n, adj, start):
    dist = [-1] * (n + 1)
    dist[start] = 0
    q = deque([start])

    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)

    return dist

def build_dist_matrix(n, adj):
    dist_matrix = []
    for i in range(1, n + 1):
        dist_matrix.append(bfs(n, adj, i))
    return dist_matrix

