import math

def solution(input_str):
    parts = input_str.strip().split()
    l, r = int(parts[0]), int(parts[1])

    # Sieve up to sqrt(r) to generate small primes for compositeness check
    sqrt_r = int(math.sqrt(r)) + 2
    is_prime_small = [True] * sqrt_r
    if sqrt_r >= 2:
        is_prime_small[0] = False
    if sqrt_r >= 3:
        is_prime_small[1] = False

    for i in range(2, int(math.sqrt(sqrt_r)) + 1):
        if is_prime_small[i]:
            for j in range(i * i, sqrt_r, i):
                is_prime_small[j] = False

    primes = [i for i in range(2, sqrt_r) if is_prime_small[i]]

    # Segmented sieve for range [l, r]
    n_range = r - l + 1
    is_composite = [False] * n_range

    for p in primes:
        if p * p > r:
            break
        # Find first multiple of p >= l
        start = max(p * p, (l + p - 1) // p * p)
        start_idx = start - l
        for i in range(start_idx, n_range, p):
            is_composite[i] = True

    ans = 0

    # Prime 2: 2 = 1² + 1², so it's Bob's lucky number
    if l <= 2 <= r:
        ans += 1

    # Find first number >= l that is ≡ 1 (mod 4)
    start = l + (1 - l) % 4

    # Count numbers ≡ 1 (mod 4) that are prime
    for i in range(start, r + 1, 4):
        # Skip 1 as it's not prime
        if i > 1 and not is_composite[i - l]:
            ans += 1

    return str(ans) + '\n'


