        action_type = parts[0]
        team = int(parts[1])
        actions.append((action_type, team))

    # Sort heroes by strength in descending order
    sorted_heroes = sorted(strengths, reverse=True)

    # Ensure m doesn't exceed n
    m = min(m, n)

    # Use memoization with bitmask for available heroes
    # mask bit i = 1 means hero i has been used (picked or banned)
    @lru_cache(maxsize=None)
    def solve(mask, action_idx):
        if action_idx == m:
            return 0

        action_type, team = actions[action_idx]

        if action_type == 'p':
            # Pick action
            if team == 1:
                # Team 1 maximizes (Team1 - Team2), so they want to maximize
                best = -float('inf')
                for i in range(m):
                    if not (mask & (1 << i)):
                        # Team 1 picks hero i and gets its strength
                        best = max(best, sorted_heroes[i] + solve(mask | (1 << i), action_idx + 1))
                return best
            else:
                # Team 2 minimizes (Team1 - Team2), so they want to minimize
                best = float('inf')
                for i in range(m):
                    if not (mask & (1 << i)):
                        # Team 2 picks hero i, which reduces (T1-T2) by hero's strength
                        best = min(best, -sorted_heroes[i] + solve(mask | (1 << i), action_idx + 1))
                return best
        else:
            # Ban action
            # Banned hero is removed from the pool but doesn't contribute to either team
