            else:
                # Team 2 bans - wants to minimize (T1-T2)
                best = float('inf')
                for i in range(m):
                    if not (mask & (1 << i)):
                        best = min(best, solve(mask | (1 << i), action_idx + 1))
                return best

    return str(solve(0, 0)) + '\n'


