def manhattan_dist(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def dist_to_subways(px, py, subways):
    if not subways:
        return float('inf')
    return min(manhattan_dist((px, py), s) for s in subways)

def cost_at_point(px, py, dwarves, d_off, subways):
    if not subways:
        D = float('inf')
    else:
        D = dist_to_subways(px, py, subways)

    max_c = 0
    for i in range(len(dwarves)):
        xi, yi = dwarves[i]
        direct = manhattan_dist((px, py), (xi, yi))
        subway = d_off[i] + D
        cost = min(direct, subway)
        max_c = max(max_c, cost)
    return max_c

