    m, n = int(parts[0]), int(parts[1])
    a = list(map(int, lines[1].split()))

    if n == 1:
        return f"{a[0]} 0\n"

    a.sort()

    # If we have all elements [0, m-1], a simple progression with d=1 works
    if n == m:
        return "0 1\n"

    # Compute differences between consecutive elements in sorted order
    diffs = [(a[i+1] - a[i]) % m for i in range(n - 1)]

    from collections import Counter
    cnt = Counter(diffs)

    # Find the most common difference - this is likely the actual d
    d = 0
    max_count = -1
    for diff, count in cnt.items():
        if count > max_count:
            max_count = count
            d = diff

    def check(start, step):
        """Check if starting from 'start' with step 'step' generates exactly set(a)"""
        s = set()
        for i in range(n):
            s.add((start + i * step) % m)
        return s == set(a)

    # Try each element as starting point with the most common difference
    for start in a:
        if check(start, d):
            return f"{start} {d}\n"

    # If the most common difference doesn't work, try other possibilities
    for diff, count in cnt.items():
        if diff != d and count >= max_count:
            if check(a[0], diff):
                return f"{a[0]} {diff}\n"

    return "-1\n"


