    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS to find distances from a starting node
    def bfs(start):
        visited = {start: 0}
        queue = [start]
        max_dist = 0
        farthest = start

        while queue:
            node = queue.pop(0)
            if visited[node] > max_dist:
                max_dist = visited[node]
                farthest = node
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited[neighbor] = visited[node] + 1
                    queue.append(neighbor)

        return farthest, max_dist

    # Find diameter using two BFS
    if n == 1:
        return '0\n'

    start, _ = bfs(1)
    farthest_from_start, _ = bfs(start)
    _, diameter = bfs(farthest_from_start)

    # Formula: (diameter - 1) // 2
    result = (diameter - 1) // 2
    return f"{result}\n"

