def solution(input_str):
    # Parse input
    lines = [line.strip() for line in input_str.strip().split('\n') if line.strip()]
    if not lines:
        return "0"

    n = int(lines[0])
    coords = []

    for i in range(len(lines)):
        if i == 0:
            continue
        parts = lines[i].split()
        if len(parts) >= 2:
            x, y = int(parts[0]), int(parts[1])
            coords.append((float(x), float(y)))

    MOD = 1000000007

    # Cross product of vectors OA and OB
    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if two segments strictly intersect
    def segments_intersect(p1, p2, p3, p4):
        d1 = cross_product(p3, p4, p1)
        d2 = cross_product(p3, p4, p2)
        d3 = cross_product(p1, p2, p3)
        d4 = cross_product(p1, p2, p4)
        return ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
               ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0))

    # Check if diagonal (i, j) is inside the polygon
    def is_diagonal_inside(i, j):
        if j == (i + 1) % n or i == (j + 1) % n:
            return True

        # Check against all polygon edges
        for a in range(n):
            b = (a + 1) % n
            # Skip edges touching i or j at endpoints
            if a == i or a == j or b == i or b == j:
                continue
            if segments_intersect(coords[i], coords[j], coords[a], coords[b]):
                return False
        return True

    # dp[i][j] = number of ways to triangulate subpolygon from vertex i to vertex j
    dp = [[0] * n for _ in range(n)]

    # Base case: consecutive vertices form a degenerate subpolygon (1 way - no split needed)
    for i in range(n - 1):
        dp[i][i + 1] = 1

    # Fill DP by length of subpolygon
    for length in range(2, n):  # length = j - i (gap between indices)
        for i in range(n - length):
            j = i + length
            dp[i][j] = 0

            # Try all possible split vertices k
            for k in range(i + 1, j):
                # Triangulation using triangle (i, k, j)
                # Need all three diagonals to be valid
                if (is_diagonal_inside(i, k) and 
                    is_diagonal_inside(k, j)):
                    ways = (dp[i][k] * dp[k][j]) % MOD
                    dp[i][j] = (dp[i][j] + ways) % MOD

    return str(dp[0][n - 1])

