MOD = 10**9 + 7

def mat_mul(A, B):
    n = len(A)
    m = len(B[0])
    k = len(B)
    C = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            for l in range(k):
                C[i][j] = (C[i][j] + A[i][l] * B[l][j]) % MOD
    return C

def mat_pow(A, p):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = A
    while p > 0:
        if p % 2 == 1:
            result = mat_mul(result, base)
        base = mat_mul(base, base)
        p //= 2
    return result

