def min_cost_single_element(n, cost_a, cost_b, arr):
    """For n=1, minimum cost to make the single element divisible by some d > 1"""
    if arr[0] > 1:
        # Already valid, cost is 0
        return 0

    # Find prime factors of arr[0], arr[0]-1, arr[0]+1
    def get_primes(num):
        factors = set()
        d = 2
        while d * d <= num:
            if num % d == 0:
                factors.add(d)
                while num % d == 0:
                    num //= d
            d += 1
        if num > 1:
            factors.add(num)
        return factors

    candidates = get_primes(arr[0])

    # Try each candidate to find if cost is minimal (to keep as is, modify, or remove)
    best = cost_a  # Remove the element
    for d in candidates:
        if arr[0] % d == 0:
            best = min(best, 0)
        elif (arr[0] - 1) % d == 0 or (arr[0] + 1) % d == 0:
            best = min(best, cost_b)
        elif d == arr[0] or d == arr[0] - 1 or d == arr[0] + 1:
            best = min(best, cost_b)

    return best

