    n = int(input_data.strip())

    # dp[i] will store the set of all possible sums using exactly i digits
    dp = [set() for _ in range(n + 1)]

    # Base case: 0 digits can only sum to 0
    dp[0].add(0)

    # Digits available: 1, 5, 10, 50
    digits = [1, 5, 10, 50]

    # Build up the DP table
    for i in range(1, n + 1):
        for d in digits:
            for prev_sum in dp[i-1]:
                dp[i].add(prev_sum + d)

    # Return the number of distinct sums
    return str(len(dp[n]))

