import sys
from functools import lru_cache

MOD = 10**9 + 7


def solution(s):
    """
    Solve the problem of computing f_r(n) modulo 10^9 + 7.
    f_0(n) counts coprime factorizations of n.
    f_{r+1}(n) = sum_{p*q=n} f_r(p) * f_r(q)
    """
    if not s.strip():
        return ""

    lines = s.strip().split('\n')
    if not lines:
        return ""

    q = int(lines[0])
    queries = []
    for i in range(1, len(lines)):
        line = lines[i].strip()
        if line:
            parts = line.split()
            if len(parts) >= 2:
                r, n = int(parts[0]), int(parts[1])
                queries.append((r, n))

    if not queries:
        return ""

    # Precompute smallest prime factor (SPF) up to max needed
    max_n = max(n for r, n in queries)
    MAX_N = max(max_n + 1, 1000005)

    min_prime = list(range(MAX_N))
    for i in range(2, int(MAX_N**0.5) + 1):
        if min_prime[i] == i:
            for j in range(i*i, MAX_N, i):
                if min_prime[j] == j:
                    min_prime[j] = i

    # Compute f_0(n) = 2^(distinct prime factors)
    memo_f0 = {}

    def f0_base(n):
        if n == 1:
            return 1
        if n in memo_f0:
            return memo_f0[n]

        temp = n
        cnt = 0
        while temp > 1:
            p = min_prime[temp]
            cnt += 1
            while temp % p == 0:
                temp //= p
                p = min_prime[temp]

        memo_f0[n] = pow(2, cnt, MOD)
        return memo_f0[n]

    f0_cache = [f0_base(i) for i in range(MAX_N)]

    # Memoized computation of f_r(n)
    @lru_cache(maxsize=None)
    def f_r(n, r):
        if n == 1:
            return 1
        if r == 0:
            return f0_cache[n]

        # Factorize n and get all divisors
        temp = n
        factors = []
        while temp > 1:
            p = min_prime[temp]
            cnt = 0
            while temp % p == 0:
                temp //= p
                cnt += 1
            factors.append((p, cnt))

        # Generate all divisors from prime factorization
        divs = [1]
        for p, cnt in factors:
            new_divs = []
            pk = 1
            for _ in range(cnt + 1):
                for d in divs:
                    new_divs.append(d * pk)
                pk *= p
            divs = new_divs

        # Compute sum of f_r(p) * f_r(n/p) for all divisors p
        total = 0
        for p in divs:
            q_val = n // p
            term = (f_r(p, r-1) * f_r(q_val, r-1)) % MOD
            total = (total + term) % MOD

        return total

    # Process all queries
    results = []
    for r, n in queries:
        val = f_r(n, r)
        results.append(str(val))

    return '\n'.join(results)


